import { create, fromBinary, toBinary } from "@bufbuild/protobuf"
import {
  ClientHelloSchema,
  EnvelopeSchema,
  ReplayRequestSchema,
} from "../../../../../contracts/generated/hcp/typescript/ji/hcp/v1/hcp_pb"
import type { ProblemDetails, SessionEvent, SessionSnapshot } from "./types"

const textDecoder = new TextDecoder()

export type HcpCallbacks = {
  apply: (event: SessionEvent) => void
  restore: (snapshot: SessionSnapshot) => void
  failed: (problem: ProblemDetails | Error) => void
  connected?: () => void
}

export function connectSession(
  url: string,
  sessionId: string,
  snapshotRevision: number,
  lastEventSeq: number,
  callbacks: HcpCallbacks,
): () => void {
  const socket = new WebSocket(url)
  socket.binaryType = "arraybuffer"
  const connectionId = crypto.randomUUID()

  socket.onopen = () => {
    socket.send(toBinary(EnvelopeSchema, create(EnvelopeSchema, {
      protocolVersion: 1,
      connectionId,
      payload: {
        case: "clientHello",
        value: create(ClientHelloSchema, {
          minProtocolVersion: 1,
          maxProtocolVersion: 1,
          clientId: deviceClientId(),
          requiredCapabilities: ["session.replay", "session.snapshot"],
        }),
      },
    })))
    socket.send(toBinary(EnvelopeSchema, create(EnvelopeSchema, {
      protocolVersion: 1,
      connectionId,
      payload: {
        case: "replayRequest",
        value: create(ReplayRequestSchema, {
          sessionId,
          lastAckSeq: BigInt(lastEventSeq),
          snapshotRevision: BigInt(snapshotRevision),
        }),
      },
    })))
    callbacks.connected?.()
  }

  socket.onmessage = event => {
    void binary(event.data).then(bytes => {
      const envelope = fromBinary(EnvelopeSchema, bytes)
      switch (envelope.payload.case) {
        case "snapshotChunk": {
          if (envelope.payload.value.chunkCount !== 1 || envelope.payload.value.chunkIndex !== 0) {
            callbacks.failed(new Error("unsupported chunked HCP snapshot"))
            return
          }
          const snapshot = parseJson<SessionSnapshot>(envelope.payload.value.payload)
          snapshot.snapshotRevision = Number(envelope.payload.value.snapshotRevision)
          snapshot.lastEventSeq ??= lastEventSeq
          snapshot.lastStreamSeq ??= 0
          callbacks.restore(snapshot)
          break
        }
        case "durableEvent": {
          const snapshot = parseJson<SessionSnapshot>(envelope.payload.value.payload)
          snapshot.snapshotRevision = Number(envelope.payload.value.snapshotRevision)
          snapshot.lastEventSeq = Number(envelope.payload.value.eventSeq)
          snapshot.lastStreamSeq ??= 0
          callbacks.restore(snapshot)
          break
        }
        case "transientStream": {
          const transient = parseJson<SessionEvent>(envelope.payload.value.payload)
          callbacks.apply({ ...transient, streamSeq: Number(envelope.payload.value.streamSeq) })
          break
        }
        case "error":
          callbacks.failed({
            type: `https://ji.invalid/problems/${envelope.payload.value.code}`,
            status: 0,
            code: envelope.payload.value.code,
            parameters: envelope.payload.value.parameters,
            traceId: envelope.payload.value.traceId,
            retryAfterMillis: envelope.payload.value.retryAfterMillis === undefined
              ? undefined : Number(envelope.payload.value.retryAfterMillis),
            currentRevision: envelope.payload.value.currentRevision === undefined
              ? undefined : Number(envelope.payload.value.currentRevision),
          })
          break
      }
    }).catch(failure => callbacks.failed(failure instanceof Error ? failure : new Error(String(failure))))
  }
  socket.onerror = () => callbacks.failed(new Error("HCP WebSocket transport failed"))

  return () => {
    socket.onopen = null
    socket.onmessage = null
    socket.onerror = null
    if (socket.readyState === WebSocket.OPEN || socket.readyState === WebSocket.CONNECTING) socket.close(1000, "session changed")
  }
}

function parseJson<T>(payload: Uint8Array): T {
  return JSON.parse(textDecoder.decode(payload)) as T
}

async function binary(value: unknown): Promise<Uint8Array> {
  if (value instanceof ArrayBuffer) return new Uint8Array(value)
  if (value instanceof Blob) return new Uint8Array(await value.arrayBuffer())
  throw new Error("binary HCP frame required")
}

function deviceClientId() {
  const key = "[REDACTED_CREDENTIAL]"
  const existing = localStorage.getItem(key)
  if (existing) return existing
  const created = crypto.randomUUID()
  localStorage.setItem(key, created)
  return created
}
